# Functions with No Side Effects

Pure functions are easy to test – give them input, assert output.

```javascript
// utils/format.js
export function formatCurrency(amount) {
  return `$${amount.toFixed(2)}`
}

// utils/format.test.js
import { formatCurrency } from './format'

describe('formatCurrency', () => {
  it('formats positive numbers', () => {
    expect(formatCurrency(5)).toBe('$5.00')
  })
  it('handles zero', () => {
    expect(formatCurrency(0)).toBe('$0.00')
  })
})
```

# Composables Need a Vue Context

Composables that use `ref`, `computed`, or lifecycle hooks need to run inside a Vue component context. Use `@vue/test-utils`'s `mount` or create a test component.

```javascript
// composables/useCounter.js
import { ref } from 'vue'
export function useCounter(initial = 0) {
  const count = ref(initial)
  const increment = () => count.value++
  return { count, increment }
}

// composables/useCounter.test.js
import { describe, it, expect } from 'vitest'
import { useCounter } from './useCounter'

describe('useCounter', () => {
  it('initializes with default value', () => {
    const { count } = useCounter()
    expect(count.value).toBe(0)
  })
  it('increments count', () => {
    const { count, increment } = useCounter(5)
    increment()
    expect(count.value).toBe(6)
  })
})
```

No special setup needed because `ref` and `computed` work standalone.

If your composable uses `onMounted`, you need to mount it in a component:

```javascript
// composables/useMounted.js
import { onMounted, ref } from 'vue'
export function useMounted() {
  const isMounted = ref(false)
  onMounted(() => { isMounted.value = true })
  return { isMounted }
}

// composables/useMounted.test.js
import { mount } from '@vue/test-utils'
import { defineComponent } from 'vue'
import { useMounted } from './useMounted'

describe('useMounted', () => {
  it('sets isMounted to true after mount', () => {
    const TestComponent = defineComponent({
      setup() {
        const { isMounted } = useMounted()
        return { isMounted }
      },
      template: '<div>{{ isMounted }}</div>'
    })
    const wrapper = mount(TestComponent)
    expect(wrapper.vm.isMounted).toBe(true)
  })
})
```
